import{_ as e,c as r,o as t,a2 as o}from"./chunks/framework.DdOM6S6U.js";const p=JSON.parse('{"title":"RegisterController","description":"","frontmatter":{"sidebarPos":6,"sidebarTitle":"RegisterController"},"headers":[],"relativePath":"system-reference/backend/http/controllers/auth/register-controller.md","filePath":"system-reference/backend/http/controllers/auth/register-controller.md","lastUpdated":1778363927000}'),a={name:"system-reference/backend/http/controllers/auth/register-controller.md"},s=o('<h1 id="registercontroller" tabindex="-1">RegisterController <a class="header-anchor" href="#registercontroller" aria-label="Permalink to &quot;RegisterController&quot;">​</a></h1><p><strong>File</strong>: <code>src/Http/Controllers/Auth/RegisterController.php</code><br><strong>Namespace</strong>: <code>Unusualify\\Modularous\\Http\\Controllers\\Auth</code><br><strong>Extends</strong>: <code>Auth\\Controller</code></p><p>Handles direct user registration (without email pre-verification). When the <code>email_verified_register</code> config option is enabled, this controller redirects users to the <a href="./pre-register-controller">PreRegisterController</a> flow instead.</p><h2 id="methods" tabindex="-1">Methods <a class="header-anchor" href="#methods" aria-label="Permalink to &quot;Methods&quot;">​</a></h2><h3 id="showform-view-redirectresponse" tabindex="-1"><code>showForm(): View|RedirectResponse</code> <a class="header-anchor" href="#showform-view-redirectresponse" aria-label="Permalink to &quot;`showForm(): View|RedirectResponse`&quot;">​</a></h3><p>Displays the registration form. If <code>modularous.email_verified_register</code> is <code>true</code>, redirects to the email verification form (<code>PreRegisterController::showEmailForm</code>).</p><h3 id="register-request-request-jsonresponse-redirectresponse" tabindex="-1"><code>register(Request $request): JsonResponse|RedirectResponse</code> <a class="header-anchor" href="#register-request-request-jsonresponse-redirectresponse" aria-label="Permalink to &quot;`register(Request $request): JsonResponse|RedirectResponse`&quot;">​</a></h3><p>Processes the registration submission:</p><ol><li>If <code>email_verified_register</code> is enabled, returns an error and redirects to the email form.</li><li>Validates the request via <code>validator()</code>.</li><li>Fires <code>ModularousUserRegistering</code> event.</li><li>Creates a <code>Company</code> record (personal if no company name provided).</li><li>Creates a <code>User</code> record attached to the company.</li><li>Assigns the <code>client-manager</code> role.</li><li>Fires <code>ModularousUserRegistered</code> event.</li><li>Returns a success response with redirect to the registration success page.</li></ol><h3 id="validator-array-data-validator" tabindex="-1"><code>validator(array $data): Validator</code> <a class="header-anchor" href="#validator-array-data-validator" aria-label="Permalink to &quot;`validator(array $data): Validator`&quot;">​</a></h3><p>Returns a validator with the rules from <code>rules()</code>.</p><h3 id="rules-array" tabindex="-1"><code>rules(): array</code> <a class="header-anchor" href="#rules-array" aria-label="Permalink to &quot;`rules(): array`&quot;">​</a></h3><table><thead><tr><th>Field</th><th>Rules</th></tr></thead><tbody><tr><td><code>name</code></td><td>required, string, max:255</td></tr><tr><td><code>surname</code></td><td>required, string, max:255</td></tr><tr><td><code>email</code></td><td>required, string, email, max:255, unique in users table</td></tr><tr><td><code>password</code></td><td>required, confirmed, meets <code>Password::defaults()</code></td></tr></tbody></table><h3 id="success-view" tabindex="-1"><code>success(): View</code> <a class="header-anchor" href="#success-view" aria-label="Permalink to &quot;`success(): View`&quot;">​</a></h3><p>Renders a success page after registration, with a button linking to the login form.</p><h2 id="registration-modes" tabindex="-1">Registration Modes <a class="header-anchor" href="#registration-modes" aria-label="Permalink to &quot;Registration Modes&quot;">​</a></h2><p>Modularous supports two registration flows controlled by <code>modularous.email_verified_register</code>:</p><table><thead><tr><th>Mode</th><th>Flow</th></tr></thead><tbody><tr><td><strong>Direct</strong> (<code>false</code>)</td><td><code>RegisterController</code> — user fills form → account created immediately</td></tr><tr><td><strong>Email-verified</strong> (<code>true</code>)</td><td><code>PreRegisterController</code> → email verification → <code>CompleteRegisterController</code></td></tr></tbody></table><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./pre-register-controller">PreRegisterController</a> — email verification step before registration</li><li><a href="./complete-register-controller">CompleteRegisterController</a> — completes registration after email verification</li><li><a href="./login-controller">LoginController</a> — post-registration login</li></ul>',20),i=[s];function d(l,n,c,h,u,m){return t(),r("div",null,i)}const f=e(a,[["render",d]]);export{p as __pageData,f as default};
